#include <vector>
#include <algorithm>
#include <random>
#include <chrono>
#include <cstdio>
using namespace std::chrono;

int main() {
    const int N = 1 << 20;
    std::vector<int> data(N);
    std::mt19937 rng(42);
    for (int& x : data) x = rng() % 256;   // values 0..255

    auto bench = [&]{
        long sum = 0;
        auto t0 = high_resolution_clock::now();
        for (int rep = 0; rep < 100; ++rep)
            for (int x : data)
                if (x >= 128) sum += x;       // data-dependent branch
        auto t1 = high_resolution_clock::now();
        printf("%ld ns (sum=%ld)\n", duration_cast<nanoseconds>(t1-t0).count(), sum);
    };

    bench();                       // unsorted: ~random branch -> many mispredicts
    std::sort(data.begin(), data.end());
    bench();                       // sorted: long no-run then long yes-run -> predicted
}
// Identical arithmetic; the sorted run is typically several times faster.

#include <cstdint>

// Branchy: unpredictable comparison can mispredict.
long sum_branchy(const int* a, int n, int thr) {
    long s = 0;
    for (int i = 0; i < n; ++i)
        if (a[i] >= thr) s += a[i];
    return s;
}

// Branchless: mask is 0 or -1; add a[i] only when mask set. No branch to mispredict.
long sum_branchless(const int* a, int n, int thr) {
    long s = 0;
    for (int i = 0; i < n; ++i) {
        long mask = -(long)(a[i] >= thr);   // 0 or 0xFFFF...
        s += a[i] & mask;
    }
    return s;
}

// Branch hints for a biased check (rare error path pushed cold).
inline void on_order(bool ok) {
    if (ok) [[likely]] { /* fast path, laid out straight-line */ }
    else    [[unlikely]] { /* rare reject path */ }
}

#include <algorithm>
#include <cstdint>

inline int clamp_bl(int x, int lo, int hi) {
    return std::min(std::max(x, lo), hi);   // usually lowered to branchless ops
}

inline long select_bl(bool cond, long a, long b) {
    long m = -(long)cond;        // 0 or 0xFFFF...FFFF
    return (a & m) | (b & ~m);   // no branch
}
